      python3 book_demo.py search WORD  (finds WORD across chapters)
      python3 book_demo.py html         (writes book.html)
"""
import json, sys, html as _h

BOOK = {'title': 'The Shadow of the necromancer Sylas', 'author': 'Signature original', 'genre': 'Wizard Schools', 'chapters': [{'n': 1, 'title': 'The Call', 'text': "They left Dragonpeak at dusk, the road winding into the unknown. Behind them, lights went out one by one as the necromancer Sylas's shadow spread. Ahead: everything.\n\nLyra Stone was mending a fence in Dragonpeak when the sky went dark at noon. The elders whispered: the necromancer Sylas had taken the Last Dragon Egg, and the old magic was failing. Prophecy or not, someone had to go.\n\nthe dwarf Bram Ironhold arrived with a pack, a sword, and no patience for goodbyes. 'You're the one the songs mean,' the dwarf Bram Ironhold said. 'the Last Dragon Egg chose you. Don't argue with songs.'"}, {'n': 2, 'title': 'Trials of the Road', 'text': "On the seventh night, Lyra Stone found the Last Dragon Egg's trail — a shimmer in the air, a song half-heard. It was close now. And the necromancer Sylas knew they were coming.\n\nThey were ambushed by the necromancer Sylas's riders at the enchanted glade. Lyra Stone fought with a mithril blade borrowed from the dwarf Bram Ironhold, and learned that bravery is mostly refusing to run at the right moment.\n\nThe road through Dragonpeak tested them daily: a bridge held by a troll who demanded riddles, a forest where the trees walked, a river that flowed uphill. the dwarf Bram Ironhold's wit and Lyra Stone's courage saw them through each."}, {'n': 3, 'title': 'The Descent', 'text': "They found the Last Dragon Egg in the vault of whispers, guarded by the dragon Karthax. The beast spoke: 'Take it, little bearer, if you can answer: what is stronger than dragonfire?' Lyra Stone answered: 'even the smallest can change the world.' The dragon bowed and let them pass.\n\nthe Last Dragon Egg blazed at Lyra Stone's touch, recognizing its bearer. Power flooded through them — and with it, the terrible knowledge of its price. Every magic, the seer had said, is a promise. This one demanded everything.\n\nAlarms rang. the necromancer Sylas's army closed in. the dwarf Bram Ironhold barred the door with a fallen pillar and grinned. 'Go,' they said. 'I'll hold them.' Lyra Stone refused to leave — so they held it together, back to back, as the dark came on."}, {'n': 4, 'title': 'The Price', 'text': "They escaped the fortress by griffon, the Last Dragon Egg burning like a small sun. But the dwarf Bram Ironhold was wounded, and the wound festered with dark magic. The healers said only the Last Dragon Egg itself could cure it — at the cost of its power.\n\nThey marched on the necromancer Sylas's stronghold with the Last Dragon Egg dark but their hearts lit. Lyra Stone carried it anyway, empty as it was. Symbols, the dwarf Bram Ironhold said, have their own magic.\n\nThen the freed prisoners arrived — an army of the grateful, farmers with pitchforks and smiths with hammers, all come to stand with the bearer of the Last Dragon Egg. Lyra Stone understood at last: the promise was never the crystal. It was this."}, {'n': 5, 'title': 'The Breaking of the Dark', 'text': "Lyra Stone fought with the mithril blade and no magic at all — only skill, and love of Dragonpeak, and the dwarf Bram Ironhold shouting from the lines. the necromancer Sylas fought with hate and sorcery, and for a long while hate seemed stronger.\n\nThe army of the dark broke and ran. Dragonpeak was free. Lyra Stone stood in the sudden silence holding the Last Dragon Egg, which was only a crystal again — but a crystal that had kept its promise.\n\nThen Lyra Stone remembered the seer's words and the dragon's riddle, and did the last thing the necromancer Sylas expected: Lyra Stone offered mercy. 'Yield,' Lyra Stone said, 'and live.' the necromancer Sylas laughed — and in that laugh, the dark wavered."}, {'n': 6, 'title': 'The Return', 'text': "They came home to Dragonpeak in spring, when the orchards bloomed. The songs had already arrived ahead of them, as songs do, and every verse was wrong in the details and right in the heart.\n\nAnd the choice, the songs say, is always the same: even the smallest can change the world. In Dragonpeak and everywhere, forever.\n\nthe dwarf Bram Ironhold was given the highest honor of Dragonpeak and immediately used it to demand better roads. Lyra Stone was offered a throne and laughed until they cried. 'I mend fences,' Lyra Stone said."}]}

def word_count():
    return sum(len(c["text"].split()) for c in BOOK["chapters"])

def print_book(ch=None):
    print("=" * 64)
    print(BOOK["title"].upper(), "\nby", BOOK["author"], "-", BOOK["genre"])
    print("=" * 64)
    for c in BOOK["chapters"]:
        if ch and c["n"] != ch:
            continue
        print("\n\nCHAPTER %d: %s\n%s" % (c["n"], c["title"], "-" * 40))
        print(c["text"])
    print("\n[%d words, %d chapters — complete]" % (word_count(), len(BOOK["chapters"])))

def search(word):
    w = word.lower()
    for c in BOOK["chapters"]:
        for i, para in enumerate(c["text"].split("\n\n")):
            if w in para.lower():
                print("[ch %d, para %d] %s..." % (c["n"], i + 1, para[:160].replace("\n", " ")))

def write_html(path="book.html"):
    parts = ["<html><head><meta charset='utf-8'><title>%s</title></head><body>" % _h.escape(BOOK["title"])]
    parts.append("<h1>%s</h1><p><i>by %s — %s</i></p>" % (_h.escape(BOOK["title"]), _h.escape(BOOK["author"]), _h.escape(BOOK["genre"])))
    for c in BOOK["chapters"]:
        parts.append("<h2>Chapter %d: %s</h2>" % (c["n"], _h.escape(c["title"])))
        for para in c["text"].split("\n\n"):
            parts.append("<p>%s</p>" % _h.escape(para))
    parts.append("</body></html>")
    open(path, "w").write("\n".join(parts))
    print("wrote", path)

if __name__ == "__main__":
    a = sys.argv[1:]
    if a and a[0] == "html":
        write_html()
    elif len(a) >= 2 and a[0] == "search":
        search(a[1])
    elif a and a[0].isdigit():
        print_book(int(a[0]))
    else:
        print_book()

